import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Search, MapPin, FileText, Home, DollarSign, Calendar,
  User, Download, Eye, Filter, ChevronRight, ChevronLeft,
  Building, Phone, Mail, Clock, ExternalLink, Printer,
  Star, Share2, BookOpen, Gavel, Map, AlertCircle
} from 'lucide-react';

// Types for real public records
interface PropertyRecord {
  parcelId: string;
  address: string;
  owner: string;
  assessedValue: number;
  taxAmount: number;
  yearBuilt: number;
  squareFeet: number;
  lotSize: string;
  propertyType: string;
  lastSaleDate: string;
  lastSalePrice: number;
  zoning: string;
  schoolDistrict: string;
  latitude?: number;
  longitude?: number;
}

interface Document {
  id: string;
  title: string;
  type: 'deed' | 'permit' | 'minutes' | 'ordinance' | 'resolution' | 'contract' | 'report';
  date: string;
  department: string;
  fileSize: string;
  pages: number;
  publicUrl?: string;
}

interface TaxRecord {
  year: number;
  assessedValue: number;
  taxAmount: number;
  paid: boolean;
  paidDate?: string;
  delinquent: boolean;
}

interface Permit {
  permitNumber: string;
  type: string;
  address: string;
  applicant: string;
  contractor?: string;
  issuedDate: string;
  expiryDate: string;
  status: 'active' | 'expired' | 'completed' | 'cancelled';
  valuation: number;
  description: string;
}

const PublicRecordsApp: React.FC = () => {
  // State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchType, setSearchType] = useState<'all' | 'property' | 'documents' | 'permits'>('all');
  const [selectedProperty, setSelectedProperty] = useState<PropertyRecord | null>(null);
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'search' | 'property' | 'documents' | 'permits' | 'meetings'>('search');
  
  // Sample Benton County data
  const sampleProperties: PropertyRecord[] = [
    {
      parcelId: '12345678901',
      address: '123 Columbia Dr, Richland, WA 99352',
      owner: 'SMITH JOHN & JANE',
      assessedValue: 385000,
      taxAmount: 4235.50,
      yearBuilt: 2005,
      squareFeet: 2340,
      lotSize: '0.25 acres',
      propertyType: 'Single Family Residential',
      lastSaleDate: '2020-06-15',
      lastSalePrice: 350000,
      zoning: 'R-1',
      schoolDistrict: 'Richland School District',
      latitude: 46.2856,
      longitude: -119.2937
    },
    {
      parcelId: '23456789012',
      address: '456 George Washington Way, Richland, WA 99352',
      owner: 'JOHNSON FAMILY TRUST',
      assessedValue: 525000,
      taxAmount: 5775.00,
      yearBuilt: 1998,
      squareFeet: 3100,
      lotSize: '0.33 acres',
      propertyType: 'Single Family Residential',
      lastSaleDate: '2019-03-22',
      lastSalePrice: 480000,
      zoning: 'R-1',
      schoolDistrict: 'Richland School District'
    },
    {
      parcelId: '34567890123',
      address: '789 Jadwin Ave, Kennewick, WA 99336',
      owner: 'WILLIAMS ROBERT',
      assessedValue: 295000,
      taxAmount: 3245.00,
      yearBuilt: 1985,
      squareFeet: 1850,
      lotSize: '0.18 acres',
      propertyType: 'Single Family Residential',
      lastSaleDate: '2021-11-30',
      lastSalePrice: 275000,
      zoning: 'R-2',
      schoolDistrict: 'Kennewick School District'
    }
  ];

  const sampleDocuments: Document[] = [
    {
      id: 'DOC001',
      title: 'City Council Meeting Minutes - January 2024',
      type: 'minutes',
      date: '2024-01-15',
      department: 'City Clerk',
      fileSize: '2.4 MB',
      pages: 45
    },
    {
      id: 'DOC002',
      title: 'Warranty Deed - 123 Columbia Dr',
      type: 'deed',
      date: '2020-06-15',
      department: 'Recorder',
      fileSize: '156 KB',
      pages: 3
    },
    {
      id: 'DOC003',
      title: 'Building Permit BP-2024-0123',
      type: 'permit',
      date: '2024-01-10',
      department: 'Building',
      fileSize: '890 KB',
      pages: 12
    },
    {
      id: 'DOC004',
      title: 'Ordinance 2024-01: Zoning Amendment',
      type: 'ordinance',
      date: '2024-01-01',
      department: 'Planning',
      fileSize: '445 KB',
      pages: 8
    }
  ];

  const samplePermits: Permit[] = [
    {
      permitNumber: 'BP-2024-0123',
      type: 'Building',
      address: '123 Columbia Dr, Richland, WA',
      applicant: 'John Smith',
      contractor: 'ABC Construction LLC',
      issuedDate: '2024-01-10',
      expiryDate: '2024-07-10',
      status: 'active',
      valuation: 25000,
      description: 'Kitchen remodel and electrical upgrade'
    },
    {
      permitNumber: 'EP-2024-0045',
      type: 'Electrical',
      address: '456 George Washington Way, Richland, WA',
      applicant: 'Johnson Family Trust',
      issuedDate: '2024-01-05',
      expiryDate: '2024-04-05',
      status: 'active',
      valuation: 5000,
      description: 'Solar panel installation'
    }
  ];

  // Search function
  const performSearch = () => {
    if (!searchQuery.trim()) return;
    
    setLoading(true);
    const query = searchQuery.toLowerCase();
    const results: any[] = [];

    // Search properties
    if (searchType === 'all' || searchType === 'property') {
      const propertyResults = sampleProperties.filter(p => 
        p.address.toLowerCase().includes(query) ||
        p.owner.toLowerCase().includes(query) ||
        p.parcelId.includes(query)
      );
      results.push(...propertyResults.map(p => ({ ...p, resultType: 'property' })));
    }

    // Search documents
    if (searchType === 'all' || searchType === 'documents') {
      const docResults = sampleDocuments.filter(d =>
        d.title.toLowerCase().includes(query) ||
        d.department.toLowerCase().includes(query)
      );
      results.push(...docResults.map(d => ({ ...d, resultType: 'document' })));
    }

    // Search permits
    if (searchType === 'all' || searchType === 'permits') {
      const permitResults = samplePermits.filter(p =>
        p.permitNumber.toLowerCase().includes(query) ||
        p.address.toLowerCase().includes(query) ||
        p.applicant.toLowerCase().includes(query)
      );
      results.push(...permitResults.map(p => ({ ...p, resultType: 'permit' })));
    }

    setTimeout(() => {
      setSearchResults(results);
      setLoading(false);
    }, 500);
  };

  // Property Detail View
  const PropertyDetailView = ({ property }: { property: PropertyRecord }) => (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-white rounded-lg shadow-lg p-6"
    >
      {/* Property Header */}
      <div className="border-b pb-4 mb-4">
        <div className="flex justify-between items-start">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">{property.address}</h2>
            <p className="text-gray-600 mt-1">Parcel ID: {property.parcelId}</p>
          </div>
          <div className="flex gap-2">
            <button className="p-2 text-gray-600 hover:bg-gray-100 rounded">
              <Printer className="w-5 h-5" />
            </button>
            <button className="p-2 text-gray-600 hover:bg-gray-100 rounded">
              <Share2 className="w-5 h-5" />
            </button>
            <button className="p-2 text-gray-600 hover:bg-gray-100 rounded">
              <Star className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>

      {/* Property Details Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Ownership Information */}
        <div className="bg-gray-50 rounded-lg p-4">
          <h3 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
            <User className="w-5 h-5 text-blue-600" />
            Ownership Information
          </h3>
          <dl className="space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-gray-600">Owner:</dt>
              <dd className="font-medium">{property.owner}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Last Sale Date:</dt>
              <dd>{property.lastSaleDate}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Last Sale Price:</dt>
              <dd className="font-medium">${property.lastSalePrice.toLocaleString()}</dd>
            </div>
          </dl>
        </div>

        {/* Property Characteristics */}
        <div className="bg-gray-50 rounded-lg p-4">
          <h3 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
            <Home className="w-5 h-5 text-green-600" />
            Property Details
          </h3>
          <dl className="space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-gray-600">Type:</dt>
              <dd>{property.propertyType}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Year Built:</dt>
              <dd>{property.yearBuilt}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Square Feet:</dt>
              <dd>{property.squareFeet.toLocaleString()} sq ft</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Lot Size:</dt>
              <dd>{property.lotSize}</dd>
            </div>
          </dl>
        </div>

        {/* Tax Information */}
        <div className="bg-gray-50 rounded-lg p-4">
          <h3 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
            <DollarSign className="w-5 h-5 text-purple-600" />
            Tax Assessment
          </h3>
          <dl className="space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-gray-600">Assessed Value:</dt>
              <dd className="font-medium">${property.assessedValue.toLocaleString()}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Annual Tax:</dt>
              <dd className="font-medium text-purple-600">${property.taxAmount.toLocaleString()}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">Tax Rate:</dt>
              <dd>{((property.taxAmount / property.assessedValue) * 100).toFixed(3)}%</dd>
            </div>
          </dl>
        </div>

        {/* Location Information */}
        <div className="bg-gray-50 rounded-lg p-4">
          <h3 className="font-semibold text-gray-900 mb-3 flex items-center gap-2">
            <MapPin className="w-5 h-5 text-red-600" />
            Location
          </h3>
          <dl className="space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-gray-600">Zoning:</dt>
              <dd>{property.zoning}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-gray-600">School District:</dt>
              <dd>{property.schoolDistrict}</dd>
            </div>
            {property.latitude && (
              <div className="flex justify-between">
                <dt className="text-gray-600">Coordinates:</dt>
                <dd className="text-xs">{property.latitude}, {property.longitude}</dd>
              </div>
            )}
          </dl>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="mt-6 flex flex-wrap gap-3">
        <button className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
          View Tax History
        </button>
        <button className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700">
          View on Map
        </button>
        <button className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700">
          View Documents
        </button>
        <button className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50">
          Download Report
        </button>
      </div>
    </motion.div>
  );

  // Main Search Interface
  const SearchInterface = () => (
    <div className="max-w-4xl mx-auto">
      {/* Search Bar */}
      <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
        <div className="flex gap-3 mb-4">
          {(['all', 'property', 'documents', 'permits'] as const).map(type => (
            <button
              key={type}
              onClick={() => setSearchType(type)}
              className={`px-4 py-2 rounded-lg font-medium ${
                searchType === type
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              {type.charAt(0).toUpperCase() + type.slice(1)}
            </button>
          ))}
        </div>
        
        <div className="flex gap-3">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && performSearch()}
              placeholder="Search by address, parcel ID, owner name, permit number..."
              className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
          <button
            onClick={performSearch}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium"
          >
            Search
          </button>
        </div>

        {/* Quick Search Examples */}
        <div className="mt-3 flex items-center gap-2 text-sm">
          <span className="text-gray-500">Try:</span>
          {['123 Columbia', 'Smith', 'BP-2024'].map(example => (
            <button
              key={example}
              onClick={() => {
                setSearchQuery(example);
                performSearch();
              }}
              className="text-blue-600 hover:underline"
            >
              {example}
            </button>
          ))}
        </div>
      </div>

      {/* Search Results */}
      {loading && (
        <div className="text-center py-12">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
          <p className="mt-4 text-gray-600">Searching public records...</p>
        </div>
      )}

      {!loading && searchResults.length > 0 && (
        <div className="space-y-4">
          <p className="text-gray-600 font-medium">
            Found {searchResults.length} results for "{searchQuery}"
          </p>
          
          {searchResults.map((result, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
              className="bg-white rounded-lg shadow-lg p-6 hover:shadow-xl transition-shadow"
            >
              {result.resultType === 'property' && (
                <div>
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <Home className="w-5 h-5 text-blue-600" />
                        <span className="text-sm font-medium text-blue-600">Property Record</span>
                      </div>
                      <h3 className="text-xl font-bold text-gray-900">{result.address}</h3>
                      <p className="text-gray-600 mt-1">Owner: {result.owner}</p>
                      <p className="text-gray-600">Parcel: {result.parcelId}</p>
                      <div className="mt-3 flex items-center gap-4 text-sm">
                        <span>Assessed: ${result.assessedValue.toLocaleString()}</span>
                        <span>•</span>
                        <span>{result.squareFeet} sq ft</span>
                        <span>•</span>
                        <span>Built {result.yearBuilt}</span>
                      </div>
                    </div>
                    <button
                      onClick={() => setSelectedProperty(result)}
                      className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                    >
                      View Details
                    </button>
                  </div>
                </div>
              )}

              {result.resultType === 'document' && (
                <div>
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <FileText className="w-5 h-5 text-green-600" />
                        <span className="text-sm font-medium text-green-600">Document</span>
                      </div>
                      <h3 className="text-xl font-bold text-gray-900">{result.title}</h3>
                      <div className="mt-2 flex items-center gap-4 text-sm text-gray-600">
                        <span>{result.department}</span>
                        <span>•</span>
                        <span>{result.date}</span>
                        <span>•</span>
                        <span>{result.pages} pages</span>
                        <span>•</span>
                        <span>{result.fileSize}</span>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700">
                        View
                      </button>
                      <button className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50">
                        Download
                      </button>
                    </div>
                  </div>
                </div>
              )}

              {result.resultType === 'permit' && (
                <div>
                  <div className="flex items-start justify-between">
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <Building className="w-5 h-5 text-purple-600" />
                        <span className="text-sm font-medium text-purple-600">Permit</span>
                      </div>
                      <h3 className="text-xl font-bold text-gray-900">{result.permitNumber}</h3>
                      <p className="text-gray-600 mt-1">{result.address}</p>
                      <p className="text-gray-600">{result.description}</p>
                      <div className="mt-3 flex items-center gap-4 text-sm">
                        <span className={`px-2 py-1 rounded ${
                          result.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-700'
                        }`}>
                          {result.status.toUpperCase()}
                        </span>
                        <span>Issued: {result.issuedDate}</span>
                        <span>•</span>
                        <span>Value: ${result.valuation.toLocaleString()}</span>
                      </div>
                    </div>
                    <button className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700">
                      View Permit
                    </button>
                  </div>
                </div>
              )}
            </motion.div>
          ))}
        </div>
      )}

      {!loading && searchResults.length === 0 && searchQuery && (
        <div className="bg-white rounded-lg shadow-lg p-12 text-center">
          <Search className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <p className="text-gray-600">No results found for "{searchQuery}"</p>
          <p className="text-sm text-gray-500 mt-2">Try searching with different keywords</p>
        </div>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b">
        <div className="container mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-6">
              <h1 className="text-2xl font-bold text-gray-900">
                Benton County Public Records
              </h1>
              <nav className="hidden md:flex gap-1">
                {[
                  { id: 'search', label: 'Search', icon: Search },
                  { id: 'property', label: 'Property', icon: Home },
                  { id: 'documents', label: 'Documents', icon: FileText },
                  { id: 'permits', label: 'Permits', icon: Building },
                  { id: 'meetings', label: 'Meetings', icon: Gavel }
                ].map(tab => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as any)}
                    className={`flex items-center gap-2 px-4 py-2 rounded-lg ${
                      activeTab === tab.id
                        ? 'bg-blue-50 text-blue-600'
                        : 'text-gray-600 hover:bg-gray-50'
                    }`}
                  >
                    <tab.icon className="w-4 h-4" />
                    {tab.label}
                  </button>
                ))}
              </nav>
            </div>
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <Clock className="w-4 h-4" />
              <span>Office Hours: Mon-Fri 8am-5pm</span>
              <span>•</span>
              <Phone className="w-4 h-4" />
              <span>(509) 736-3000</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 py-8">
        {selectedProperty ? (
          <div>
            <button
              onClick={() => setSelectedProperty(null)}
              className="mb-4 text-blue-600 hover:underline flex items-center gap-2"
            >
              <ChevronLeft className="w-4 h-4" />
              Back to search
            </button>
            <PropertyDetailView property={selectedProperty} />
          </div>
        ) : (
          <SearchInterface />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-gray-100 border-t mt-12">
        <div className="container mx-auto px-4 py-6">
          <div className="text-center text-sm text-gray-600">
            <p>Benton County Public Records • 620 Market St, Prosser, WA 99350</p>
            <p className="mt-2">This is public information provided as a service to citizens</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default PublicRecordsApp;